window.bookSummaryJSON = "<p>Mindy Starns Clark is an ECPA best-selling author. Following <i>A Penny for Your Thoughts</i>, this is the second installment in her Million Dollar Mystery series. Callie returns home to help a young woman, Shayna, prepare for a new job. But they soon discover the dead body of Shayna’s boyfriend. Only by turning to God for help can Callie solve this deadly mystery.</p>"; 
